// spec: .qa/e2e/specs/tender-drafts.md
// seed: tests/seed.company.spec.ts
import { test, expect } from '@playwright/test';
import path from 'path';
import { fillFreeTenderWizardToTerms, expectNoPayment, journal } from '../_helpers/tender-wizard';

test.use({ storageState: path.join(__dirname, '../../../auth/company.json') });

const DRAFT = 'טיוטה – הפרסום לא הושלם';

test.describe('Tender drafts — «המכרזים שלי» (company)', () => {
  let draftId: string | undefined;
  const title = `QA-AUTO-bc890b-${Date.now()}`;

  test.afterAll(() => {
    // Cleanup: a draft's «•••» menu has only «צפייה בפרטי המכרז» (no delete, checked 21.10.2026) → record the id for manual cleanup.
    if (draftId) journal(`tender draft ${draftId} «${title}» (tender-drafts 1.2, no delete option)`);
  });

  test('A tender stopped before «פרסום המכרז» becomes a draft and can be continued @desktop @data #bc890b', async ({ page }) => {
    test.setTimeout(120_000);

    // 1–2. Free tender wizard up to step 4 (terms), without «פרסום המכרז»
    draftId = await fillFreeTenderWizardToTerms(page, title, 'QA-AUTO — לא לפרסם');
    test.info().annotations.push({ type: 'qa-auto-data', description: `tender draft ${draftId} «${title}»` });

    // 3. «המכרזים שלי»
    await page.goto('/tenders?mine=1');
    const card = page.getByRole('listitem').filter({ has: page.getByRole('heading', { level: 3, name: title, exact: true }) });
    await expect(card).toHaveCount(1);
    // Expected: badge «טיוטה – הפרסום לא הושלם» (not «ממתין לתשלום»), «מס׳ הצעות» 0
    await expect(card.getByText(DRAFT, { exact: true })).toBeVisible();
    await expect(card).not.toContainText('ממתין לתשלום');
    await expect(card).toContainText(/מס׳ הצעות\s*0(?!\d)/);

    // 4. Continue publishing from the card
    await card.getByRole('link', { name: `לפרטי המכרז: ${title}` }).click();
    const details = page.getByRole('dialog', { name: 'פרטי המכרז' });
    await expect(details.getByText(DRAFT, { exact: true })).toBeVisible();
    await details.getByRole('link', { name: 'להשלמת הפרסום' }).click();

    // Expected: the wizard of this draft (id in URL), not a new empty wizard from step 1
    await expect(page).toHaveURL(new RegExp(`/publish/tender/[a-z]+\\?id=${draftId}`));
    await expect(page.getByText('שלב 1 מתוך 4')).toHaveCount(0);
    await expect(page.getByText(/^שלב [2-4] מתוך 4$/)).toBeVisible();
    // ...with the entered title (shown on step 3 «פרטי המכרז»)
    if (!/\/details\?/.test(page.url())) await page.getByRole('link', { name: 'חזרה' }).click();
    await expect(page).toHaveURL(new RegExp(`/publish/tender/details\\?id=${draftId}`));
    await expect(page.getByRole('textbox', { name: /^כותרת/ })).toHaveValue(title);
    await expectNoPayment(page);
  });
});
